using CargoWise.Types;
using NUnit.Framework;

namespace Enterprise.Client.UPE.Business.DataImport.Level1FileFormat.Testing
{
	public class Level1RecordTest : TestCase
	{
		public void TestIsEmpty()
		{
			Level1Record level1Record = new Level1Record();
			level1Record.AddRecordLine("US2795AU9639040422              D3824ARFY9JH2000003824ARFY9JH           N 1 19   LBS US          USDNNNN           USDAKE32156QF    09642             USD         USD5100      USDN0 N   NEDI  19APR200419 LBS         USDD1    NNN NN  NN  N USD           USD    T1                      19APR20040000           5100       P/PNRE       19   LBSNNC0000051901QF12            N N 1   N ");
			level1Record.AddRecordLine("US2795AU9639040422              D3824ARFY9JH2020001Z3824AR6640806327                 19     19     2    N                                                            7709705048E                AU09639  S1AU9639TF.113B2004-04-21                              Y                                                                             AUDNNNNNBI                                  ");
			AssertEquals(false, level1Record.IsEmpty);
			level1Record = new Level1Record();
			AssertEquals(true, level1Record.IsEmpty);
			level1Record.AddRecordLine("            000000               W3188389763200000W3188389763                                                                                                                                                                                                                                                                                        B2015510377                  N       ");
			level1Record.AddRecordLine("            000000               W3188389763202000W3188389763                                                                                                                                   AU09639  S1AU9639T3.076B2005-03-16                              Y                                                                             AUDNNNNNBI                                  ");
			AssertEquals(true, level1Record.IsEmpty);
		}

		public void Test600000LinesCollection()
		{
			AssertNotNull(new Level1Record()._600000Lines);
		}

		public void Test500000LinesCollection()
		{
			AssertNotNull(new Level1Record()._500000Lines);
		}

		public void TestToString()
		{
			Level1Record level1Record = new Level1Record();
			level1Record._200000 = new _200000Line("US2795AU9639040422              D3824ARFY9JH2000003824ARFY9JH           N 1 19   LBS US          USDNNNN           USDAKE32156QF    09642             USD         USD5100      USDN0 N   NEDI  19APR200419 LBS         USDD1    NNN NN  NN  N USD           USD    T1                      19APR20040000           5100       P/PNRE       19   LBSNNC0000051901QF12            N N 1   N ");
			level1Record._202000 = new _202000Line("US2795AU9639040422              D3824ARFY9JH2020001Z3824AR6640806327                 19     19     2    N                                                            7709705048E                AU09639  S1AU9639TF.113B2004-04-21                              Y                                                                             AUDNNNNNBI                                  ");
			level1Record._300000 = new _300000Line("US2795AU9639040422              D3824ARFY9JH300000073706003824AR    BIOTECH CORP                       107 OAKWOOD DRIVE                                                     GLASTONBURY                                            CT060332481US 18606338111                                                                               11644                                         ");
			level1Record._400000 = new _400000Line("US2795AU9639040422              D3824ARFY9JH400000170520138AU0495926SNOWSILL, SONYA                                             15 LEANDER ST                                                         FALCON                                                   6210     AU 0895343637                  SNOWSILL    SNOWSILL                                                 237           ");
			level1Record._401000 = new _401000Line("US2795AU9639040422              DA4W82133K3G401000        8AU0596227WENDY PATERSON                     ContactName              GPO BOX 1609                       ABC                                SYDNEY                                                 NS2001     AU 123456789                                                                                        237           ");
			level1Record._500000Lines.Add(new _500000Line("US2795AU9639040422              D3824ARFY9JH5000006   EA SHEN MIN EXTRA STRENGTH                                                                                 600       USD11644               US                                   AU                                                                                                                                                 "));
			level1Record._500000Lines.Add(new _500000Line("US2795AU9639040422              D3824ARFY9JH5010006   EA ADVANCED SHEN MIN FOR WOMEN                                                                             600       USD11644               US                                   AU                                                                                                                                                 "));
			level1Record._600000Lines.Add(new _600000Line("US2795AU9639040422              D3947808NNSR60000099999999999    10 LBS         USD         USD          USD                             C0000092779UPS6901         NY1ZAT27736792092649                 10     AAY89758UPS                                                                                                                                                               "));
			level1Record._600000Lines.Add(new _600000Line("US2795AU9639040422              D3947808NNSR60000099999999999    11 LBS         USD         USD          USD                             C0000092779UPS6901         NY1ZAT27736792092649                 10     AAY89758UPS                                                                                                                                                               "));
			level1Record._900000 = new _900000Line("US2795AU9639040422              D4A14T9J3YYD900000                                     18APR2004EDI                   #ARN:65744051475#                                                                                                                                                                                                                                                   ");
			string expected = "US2795AU9639040422              D3824ARFY9JH2000003824ARFY9JH           N 1 19   LBS US          USDNNNN           USDAKE32156QF    09642             USD         USD5100      USDN0 N   NEDI  19APR200419 LBS         USDD1    NNN NN  NN  N USD           USD    T1                      19APR20040000           5100       P/PNRE       19   LBSNNC0000051901QF12            N N 1   N " + "\n" + "US2795AU9639040422              D3824ARFY9JH2020001Z3824AR6640806327                 19     19     2    N                                                            7709705048E                AU09639  S1AU9639TF.113B2004-04-21                              Y                                                                             AUDNNNNNBI                                  " + "\n" + "US2795AU9639040422              D3824ARFY9JH300000073706003824AR    BIOTECH CORP                       107 OAKWOOD DRIVE                                                     GLASTONBURY                                            CT060332481US 18606338111                                                                               11644                                         " + "\n" + "US2795AU9639040422              D3824ARFY9JH400000170520138AU0495926SNOWSILL, SONYA                                             15 LEANDER ST                                                         FALCON                                                   6210     AU 0895343637                  SNOWSILL    SNOWSILL                                                 237           " + "\n" + "US2795AU9639040422              DA4W82133K3G401000        8AU0596227WENDY PATERSON                     ContactName              GPO BOX 1609                       ABC                                SYDNEY                                                 NS2001     AU 123456789                                                                                        237           " + "\n" + "US2795AU9639040422              D3824ARFY9JH5000006   EA SHEN MIN EXTRA STRENGTH                                                                                 600       USD11644               US                                   AU                                                                                                                                                 " + "\n" + "US2795AU9639040422              D3824ARFY9JH5010006   EA ADVANCED SHEN MIN FOR WOMEN                                                                             600       USD11644               US                                   AU                                                                                                                                                 " + "\n" + "US2795AU9639040422              D3947808NNSR60000099999999999    10 LBS         USD         USD          USD                             C0000092779UPS6901         NY1ZAT27736792092649                 10     AAY89758UPS                                                                                                                                                               " + "\n" + "US2795AU9639040422              D3947808NNSR60000099999999999    11 LBS         USD         USD          USD                             C0000092779UPS6901         NY1ZAT27736792092649                 10     AAY89758UPS                                                                                                                                                               " + "\n" + "US2795AU9639040422              D4A14T9J3YYD900000                                     18APR2004EDI                   #ARN:65744051475#                                                                                                                                                                                                                                                   " + "\n";
			AssertMultilineASCIIEquals("ToString", expected, level1Record.ToString());
		}

		public void TestAddRecordLine()
		{
			Level1Record level1Record = new Level1Record();
			level1Record.AddRecordLine("US2795AU9639040422              D3824ARFY9JH2000003824ARFY9JH           N 1 19   LBS US          USDNNNN           USDAKE32156QF    09642             USD         USD5100      USDN0 N   NEDI  19APR200419 LBS         USDD1    NNN NN  NN  N USD           USD    T1                      19APR20040000           5100       P/PNRE       19   LBSNNC0000051901QF12            N N 1   N ");
			AssertNotNull(level1Record._200000);
			level1Record.AddRecordLine("US2795AU9639040422              D3824ARFY9JH2020001Z3824AR6640806327                 19     19     2    N                                                            7709705048E                AU09639  S1AU9639TF.113B2004-04-21                              Y                                                                             AUDNNNNNBI                                  ");
			AssertNotNull(level1Record._202000);
			level1Record.AddRecordLine("US2795AU9639040422              D3824ARFY9JH300000073706003824AR    BIOTECH CORP                       107 OAKWOOD DRIVE                                                     GLASTONBURY                                            CT060332481US 18606338111                                                                               11644                                         ");
			AssertNotNull(level1Record._300000);
			level1Record.AddRecordLine("US2795AU9639040422              D3824ARFY9JH400000170520138AU0495926SNOWSILL, SONYA                                             15 LEANDER ST                                                         FALCON                                                   6210     AU 0895343637                  SNOWSILL    SNOWSILL                                                 237           ");
			AssertNotNull(level1Record._400000);
			level1Record.AddRecordLine("US2795AU9639040422              DA4W82133K3G401000        8AU0596227WENDY PATERSON                     ContactName              GPO BOX 1609                       ABC                                SYDNEY                                                 NS2001     AU 123456789                                                                                        237           ");
			AssertNotNull(level1Record._401000);
			level1Record.AddRecordLine("US2795AU9639040422              D3824ARFY9JH5000006   EA SHEN MIN EXTRA STRENGTH                                                                                 600       USD11644               US                                   AU                                                                                                                                                 ");
			AssertEquals(1, level1Record._500000Lines.Count);
			level1Record.AddRecordLine("US2795AU9639040422              D3947808NNSR60000099999999999    10 LBS         USD         USD          USD                             C0000092779UPS6901         NY1ZAT27736792092649                 10     AAY89758UPS                                                                                                                                                               ");
			AssertEquals(1, level1Record._600000Lines.Count);
			level1Record.AddRecordLine("US2795AU9639040422              D4A14T9J3YYD900000                                     18APR2004EDI                   #ARN:65744051475#                                                                                                                                                                                                                                                   ");
			AssertNotNull(level1Record._900000);
		}

		public void TestAddRecordLines()
		{
			ZString[] level1Data = new ZString[] { "US2795AU9639040422              D3824ARFY9JH2000003824ARFY9JH           N 1 19   LBS US          USDNNNN           USDAKE32156QF    09642             USD         USD5100      USDN0 N   NEDI  19APR200419 LBS         USDD1    NNN NN  NN  N USD           USD    T1                      19APR20040000           5100       P/PNRE       19   LBSNNC0000051901QF12            N N 1   N ", "US2795AU9639040422              D3824ARFY9JH2020001Z3824AR6640806327                 19     19     2    N                                                            7709705048E                AU09639  S1AU9639TF.113B2004-04-21                              Y                                                                             AUDNNNNNBI                                  ", "US2795AU9639040422              D3824ARFY9JH300000073706003824AR    BIOTECH CORP                       107 OAKWOOD DRIVE                                                     GLASTONBURY                                            CT060332481US 18606338111                                                                               11644                                         ", "US2795AU9639040422              D3824ARFY9JH400000170520138AU0495926SNOWSILL, SONYA                                             15 LEANDER ST                                                         FALCON                                                   6210     AU 0895343637                  SNOWSILL    SNOWSILL                                                 237           ", "US2795AU9639040422              DA4W82133K3G401000        8AU0596227WENDY PATERSON                     ContactName              GPO BOX 1609                       ABC                                SYDNEY                                                 NS2001     AU 123456789                                                                                        237           ", "US2795AU9639040422              D3824ARFY9JH5000006   EA SHEN MIN EXTRA STRENGTH                                                                                 600       USD11644               US                                   AU                                                                                                                                                 ", "US2795AU9639040422              D3947808NNSR60000099999999999    11 LBS         USD         USD          USD                             C0000092779UPS6901         NY1ZAT27736792092649                 10     AAY89758UPS                                                                                                                                                               ", "US2795AU9639040422              D4A14T9J3YYD900000                                     18APR2004EDI                   #ARN:65744051475#                                                                                                                                                                                                                                                   " };
			Level1Record level1Record = new Level1Record();
			level1Record.AddRecordLines(level1Data);
			AssertNotNull(level1Record._200000);
			AssertNotNull(level1Record._202000);
			AssertNotNull(level1Record._300000);
			AssertNotNull(level1Record._400000);
			AssertNotNull(level1Record._401000);
			AssertNotNull(level1Record._900000);
			AssertEquals(1, level1Record._500000Lines.Count);
			AssertEquals(1, level1Record._600000Lines.Count);
		}
	}
}
